import {museum,resources,posts,themes,dictionaries} from './data.js';
import {analyze,aggregate,defaults,dimensionNames} from './engine.js';
import {fetchPublicComments,dedupe,safeUrl,researchSource} from './sources.js';
import {kindLabel,reviewLabel,sourceLink,provenanceBanner,provenanceCard,reviewControls,highlight} from './evidence-ui.js';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let saved,legacy;try{saved=JSON.parse(localStorage.getItem('museradar-real-v2'));legacy=JSON.parse(localStorage.getItem('museradar-v1'));}catch{}
let state=saved||{museum:legacy?.museum||museum,resources:legacy?.resources||resources,posts:structuredClone(posts),weights:[...defaults],plans:{},reviews:{},runs:[]};
state.reviews||={};state.runs||=[];
let page=location.hash.slice(1)||'overview',selected=state.posts[0]?.id,theme='亲子教育与互动',search='',filterTheme='',filterIntent='',filterSource='',filterKind='',filterReview='',from='',to='',sort='index',draft='',pending=[],importErrors=[],testResult=null;
let liveState={query:'museum',days:0,page:0,busy:false,error:'',last:null};
const nav=[['overview','◈','智能洞察总览','Overview'],['dna','▧','博物馆知识库','Museum DNA'],['social','≋','社交数据中心','Social Listening'],['analysis','⌘','需求识别与评分','AI Signal Analysis'],['insights','◉','需求洞察与机会','Audience Insights'],['studio','✦','智能营销工作台','Marketing Studio']];
function persist(){try{localStorage.setItem('museradar-real-v2',JSON.stringify(state));}catch{toast('浏览器存储不可用，本次会话仍可操作');}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),2600);}
const all=()=>state.posts.map(p=>analyze({...p,review:state.reviews[p.id]||'pending'},state.resources,state.weights));
function filtered(){return all().filter(r=>(!search||r.post.text.includes(search)||r.post.id.includes(search))&&(!filterTheme||r.theme===filterTheme)&&(!filterIntent||r.intent===filterIntent)&&(!filterSource||r.post.source===filterSource)&&(!filterKind||r.post.kind===filterKind)&&(!filterReview||r.post.review===filterReview)&&(!from||r.post.date>=from)&&(!to||r.post.date<=to));}
const analyzed=()=>filtered().filter(r=>r.post.analyzed), groups=()=>aggregate(analyzed().filter(r=>r.post.review!=='rejected')).sort((a,b)=>b[sort]-a[sort]);
function go(p){page=p;location.hash=p;render();window.scrollTo(0,0);}
const button=(text,action,primary=false)=>`<button class="${primary?'primary':''}" data-action="${action}">${text}</button>`;
const tag=(text,cls='')=>`<span class="tag ${cls}">${esc(text)}</span>`;
const empty='<div class="empty">暂无符合条件的数据。请调整筛选或导入内容。</div>';
function bar(label,value,max=100){return `<div class="bar-row"><span>${esc(label)}</span><div class="track"><i style="width:${Math.min(100,value/max*100)}%"></i></div><b>${value}</b></div>`;}
function filters(){return `<div class="filters"><input id="search" placeholder="搜索正文或内容 ID" value="${esc(search)}"><select id="theme-filter"><option value="">全部主题</option>${themes.map(t=>`<option ${t===filterTheme?'selected':''}>${t}</option>`).join('')}</select><select id="intent-filter"><option value="">全部意向</option>${['一般兴趣','潜在体验需求','明确参观计划','已经参观','历史评论/到访待核实','负面/排斥','无关内容'].map(t=>`<option ${t===filterIntent?'selected':''}>${t}</option>`).join('')}</select><select id="source-filter"><option value="">全部来源</option>${[...new Set(state.posts.map(p=>p.source))].map(t=>`<option ${t===filterSource?'selected':''}>${esc(t)}</option>`).join('')}</select><input aria-label="开始日期" id="from" type="date" value="${from}"><input aria-label="结束日期" id="to" type="date" value="${to}">${button('清除筛选','clear')}</div>`;}
function render(){if(!nav.some(n=>n[0]===page))page='overview';const current=nav.find(n=>n[0]===page),data=filtered(),dates=data.map(r=>r.post.date).filter(Boolean).sort();$('#app').innerHTML=`<aside><a class="brand" href="#overview"><span class="brand-icon">◈</span><span>MuseRadar <em>AI</em><small>AUDIENCE INTELLIGENCE</small></span></a><div class="workspace-label">工作空间 / WORKSPACE</div><nav>${nav.map(n=>`<a href="#${n[0]}" class="${n[0]===page?'active':''}"><span>${n[1]}</span><div>${n[2]}<small>${n[3]}</small></div></a>`).join('')}<a href="./guide.html" target="_blank" rel="noopener noreferrer" aria-label="使用指南（新标签页打开）"><span aria-hidden="true">?</span><div>使用指南 ↗<small>User Guide</small></div></a></nav><div class="sidebar-bottom"><span class="pulse"></span> 本地规则引擎已就绪<p>真实评论 · 可追溯来源</p><small>洞察需求，让文化被看见。</small></div></aside><div class="shell"><header><div>工作空间 <span>/</span> ${current[2]}</div><div class="header-right"><span class="museum-name">▧ ${esc(state.museum.name)}</span>${tag('真实评论 / 规则分析','teal')}<span class="avatar">云</span></div></header><main><div class="page-heading"><div><div class="eyebrow">MUSERADAR / ${current[3].toUpperCase()}</div><h1>${current[2]}</h1><p>${['从社交表达中发现尚未被看见的文化需求。','让每一次需求匹配，都有真实资源可依。','管理分析样本，保留每条洞察的来源。','从原文证据到可解释的需求信号。','将分散的兴趣，转化为值得验证的推广机会。','让洞察进入内容，让效果回到验证。'][nav.indexOf(current)]}</p></div><div class="date-label">◷ ${dates[0]||'无日期'} — ${dates.at(-1)||'无日期'}<small>原始发布时间 · 非采集时间</small></div></div>${provenanceBanner()}${({overview:overview,dna:dna,social:social,analysis:analysisPage,insights:insights,studio:studio}[page])()}<footer>真实公开评论 / 示例馆资源 · 规则评分非到馆概率 · 不保留评论者身份 <span>AI-Powered Museum Audience Intelligence</span></footer></main></div>`;bind();}
function overview(){const a=analyzed(),g=groups(),high=a.filter(r=>r.high),gs=g.slice(0,4),intent=[...new Set(a.map(r=>r.intent))];return `<section class="hero"><div>${tag('从兴趣，走向到访','light')}<h2>你的下一位观众，<br>可能还没有提到博物馆。</h2><p>连接社交需求与馆藏资源，发现有证据的营销机会。</p>${button('开始发现潜在观众需求　↗','start',true)}</div><div class="radar-art"><div class="orbit o1"></div><div class="orbit o2"></div><div class="orbit o3"></div><b>◈</b><span class="radar-label l1">文化兴趣</span><span class="radar-label l2">体验需求</span><span class="radar-label l3">馆藏资源</span></div></section>${filters()}<div class="kpis">${[['已分析社交内容数',a.length,'条','当前筛选中已分析的样本'],['已发现需求主题数',g.length,'个','固定词典主题中的非空分群'],['高潜力需求信号数',high.length,'条','分数≥70、覆盖率≥70%，排除历史和负面'],['待验证营销机会数',g.filter(x=>x.rows.some(r=>r.matches.length)).length,'项','存在资源匹配的非空主题']].map((k,i)=>`<button class="kpi" data-action="kpi${i}" title="${k[3]}"><span>${k[0]} <i>↗</i></span><strong>${k[1]}<small>${k[2]}</small></strong><p>${k[3]}</p></button>`).join('')}</div><div class="grid2"><section class="panel"><div class="panel-title"><h3>需求主题分布</h3>${tag('当前样本 · 条')}</div>${g.map(x=>`<div data-topic="${x.theme}" class="clickable">${bar(x.theme,x.n,Math.max(...g.map(z=>z.n),1))}</div>`).join('')||empty}</section><section class="panel"><div class="panel-title"><h3>评论发布时间分布</h3>${tag('样本讨论量 · 条')}</div>${trend(a)}<p class="muted">按完整年份展示原评数量；历史便利样本不代表当前热度或平台总体。</p></section><section class="panel"><h3>需求意向分布</h3>${intent.map(i=>bar(i,a.filter(r=>r.intent===i).length,a.length||1)).join('')||empty}</section><section class="panel"><div class="panel-title"><h3>推广机会优先级</h3><a href="#insights">查看全部 ↗</a></div>${gs.map((x,i)=>`<div class="rank" data-topic="${x.theme}"><b>0${i+1}</b><div><strong>${x.theme}</strong><small>${x.n} 条证据 · 宣传覆盖待核实</small></div><span>${x.index}<small>机会指数</small></span></div>`).join('')||empty}</section></div><div class="section-title"><h2>发现值得验证的机会</h2><span>AI 辅助框架 · 本地规则计算</span></div><div class="opportunities">${gs.slice(0,3).map(opCard).join('')||empty}</div>`;}
function trend(a){const valid=a.filter(r=>r.post.date),bins=new Map();for(const r of valid){const year=r.post.date.slice(0,4);bins.set(year,(bins.get(year)||0)+1);}if(!bins.size)return '<div class="empty">没有有效原始发布时间；不生成时间趋势。</div>';const rows=[...bins].sort(),max=Math.max(...rows.map(x=>x[1]),1);return `<div class="year-chart">${rows.map(([year,n])=>bar(year+' 年',n,max)).join('')}</div>`;}
function opCard(g){const r=g.rows.find(r=>r.matches.length);return `<article class="panel opportunity">${tag('待验证机会','teal')}<h3>${g.theme}</h3><p>${g.n} 条相关表达 · 历史评论 ${g.history} 条 · 平均信号 ${g.strength}</p><blockquote>“${esc((r||g.rows[0]).post.text)}”</blockquote><small>跨馆启发匹配（示例资源）：${esc(r?.matches[0]?.name||'暂无，需完善知识库')}</small><div class="card-bottom"><span>优先级 ${g.index} / 100</span><button class="text-button" data-strategy="${g.theme}">生成营销策略 ↗</button></div></article>`;}
function dna(){const fields={name:'博物馆名称',city:'城市',intro:'简介',categories:'主要馆藏类别',features:'核心展览特色',focus:'重点推广资源',audience:'适合客群及体验场景',hours:'开放时间',ticket:'门票',booking:'预约方式',restrictions:'拍照及活动限制'};return `<div class="notice">虚构示例博物馆 · 保存资料或修改资源后，所有匹配与主题统计立即重新计算。</div><section class="panel"><div class="panel-title"><h3>博物馆资料</h3>${tag('可编辑','teal')}</div><form id="museum-form"><div class="form-grid">${Object.entries(fields).map(([k,v])=>`<label>${v}<${k==='intro'||k==='restrictions'?'textarea':'input'} name="${k}" ${k==='intro'||k==='restrictions'?'':`value="${esc(state.museum[k])}"`} required>${k==='intro'||k==='restrictions'?esc(state.museum[k]):''}</${k==='intro'||k==='restrictions'?'textarea':'input'}></label>`).join('')}</div><button class="primary">保存资料并重新匹配</button></form></section><div class="section-title"><h2>展品与活动资源 <small>${state.resources.length} 项</small></h2>${button('＋ 添加资源','add-resource',true)}</div><div class="resource-grid">${state.resources.map(r=>`<article class="panel"><div class="panel-title">${tag(r.type)}<small>${r.id}</small></div><h3>${esc(r.name)}</h3><p>${esc(r.intro)}</p><div class="keywords">${r.keywords.split(/\s+/).map(k=>tag(k)).join('')}</div><p class="muted">${esc(r.conditions)}</p><div class="card-bottom"><button data-edit-resource="${r.id}">详情 / 编辑</button><button class="danger" data-delete-resource="${r.id}">删除</button></div></article>`).join('')}</div><section class="panel"><h3>知识库关键词扩展 <small>预设规则 · 非模型生成</small></h3><p>青铜器 → 古代工艺、传统铸造、历史黑科技、文物制作</p><p>亲子研学 → 孩子、动手、学习、制作、知识</p><p class="muted">匹配器使用每项资源可编辑的关键词。扩展词需加入资源关键词后才参与计算。</p></section>`;}
function social(){const rows=filtered();return `${sourcePanel()}<div class="toolbar">${button('↑ 导入 CSV / JSON','import',true)}${button('载入真实研究评论','samples')}${button('开始分析当前筛选','analyze')}${button('导出当前数据','export-posts')}<input type="file" id="file" accept=".csv,.json" hidden></div>${filters()}<div class="toolbar"><label>内容类型 <select id="kind-filter"><option value="">全部类型</option>${[['visitor-review','历史到访评论'],['public-discussion','公开社区讨论'],['imported','用户导入 / 未核实'],['manual','手动输入 / 未核实']].map(([v,l])=>`<option value="${v}" ${v===filterKind?'selected':''}>${l}</option>`).join('')}</select></label><label>人工复核 <select id="review-filter"><option value="">全部状态</option>${[['pending','待复核'],['accepted','值得参考'],['rejected','暂不采用']].map(([v,l])=>`<option value="${v}" ${v===filterReview?'selected':''}>${l}</option>`).join('')}</select></label></div><section class="panel table-panel"><div class="panel-title"><h3>真实来源与待核实输入 <small>${rows.length} 条</small></h3>${tag('点击行查看原文证据')}</div><div class="table-scroll"><table><thead><tr>${['内容 ID / 类型','原始发布时间','正文','主题 / 意向','来源 / 证据','状态 / 复核'].map(t=>`<th>${t}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr data-select="${esc(r.post.id)}"><td><b>${esc(r.post.id)}</b><small>${esc(r.post.platform)}</small>${tag(kindLabel(r.post.kind))}</td><td>${esc(r.post.date||'未知')}<small>采集：${esc(r.post.collectedAt?.slice(0,10)||'未知')}</small></td><td class="body-cell"><div class="review-preview">${esc(r.post.text)}</div><small>${esc(r.post.museumName||r.post.threadTitle||'未指定博物馆')}</small></td><td>${tag(r.post.analyzed?r.theme:'待分析')}<small>${r.post.analyzed?r.intent:'—'}</small></td><td>${esc(r.post.source)}<small>${sourceLink(r.post.evidenceUrl||r.post.sourceUrl,r.post.sourcePage?'PDF 第 '+r.post.sourcePage+' 页 · 记录 '+r.post.sourceRow:'查看原文')}</small></td><td>${tag(r.post.analyzed?'已分析':'待分析',r.post.analyzed?'teal':'')}<small>${reviewLabel(r.post.review)}</small></td></tr>`).join('')}</tbody></table>${rows.length?'':empty}</div></section>`;}
function analysisPage(){const rows=filtered(),r=testResult||all().find(r=>r.post.id===selected)||rows[0];return `<div class="notice">评分表示需求信号强弱，不代表到馆概率。规则分类可能出错，请结合原文人工审核。</div>${filters()}<div class="analysis-layout"><section class="panel signal-list"><h3>原始内容 <small>${rows.length} 条</small></h3>${rows.map(x=>`<button class="signal ${r?.post.id===x.post.id&&!testResult?'selected':''}" data-signal="${esc(x.post.id)}"><span>${esc(x.post.id)} ${tag(x.intent)}</span><p>${esc(x.post.text)}</p><small>${x.post.analyzed?`信号 ${x.score??'—'} · 覆盖率 ${x.coverage}%`:'待分析'}</small></button>`).join('')||empty}</section><div>${r?detail(r):empty}<section class="panel"><div class="panel-title"><h3>评分权重</h3>${button('重置默认','reset-weights')}</div>${dimensionNames.map((n,i)=>`<label class="weight">${n}<input aria-label="${n}权重" type="range" min="0" max="100" value="${state.weights[i]}" data-weight="${i}"><b>${state.weights[i]}%</b></label>`).join('')}<p class="muted">当前总权重 ${state.weights.reduce((a,b)=>a+b,0)}，计算时归一化；全部为零时不产生分数。</p></section><section class="panel"><h3>试一段新的社交表达</h3><textarea id="test-text" rows="3" placeholder="输入任意文本，测试规则分析…">${esc(draft)}</textarea><div class="toolbar">${button('分析文本','test',true)}${button('加入数据集','add-test')}</div><small>手动文本标记为来源未核实；不冒充真实公开评论，不进入高潜力名单。</small></section></div></div>`;}
function detail(r){if(!r.post.analyzed)return `<section class="panel"><h3>此内容尚未分析</h3><p>${esc(r.post.text)}</p>${button('开始分析当前筛选','analyze',true)}</section>`;const highlighted=highlight(r.post.text,r.hits);return `<section class="panel"><div class="panel-title"><h3>需求分析详情</h3>${tag('LOCAL RULES','teal')}</div><blockquote class="evidence">${highlighted}</blockquote>${provenanceCard(r.post)}${reviewControls(r.post)}<div class="tags">${tag(r.theme)}${tag(r.intent)}${tag(r.coverage<70?'待核实':r.high?'高潜力信号':'普通信号',r.high?'teal':'')}</div><div class="score-block"><strong>${r.score??'—'}<small>/ 100</small></strong><div>需求信号指数<p>证据覆盖率 <b>${r.coverage}%</b></p></div></div><p><b>隐含需求：</b>${esc(r.hits.join('、')||'尚无充分主题线索')}</p>${r.values.map((v,i)=>`<div class="dimension">${bar(dimensionNames[i],v??0)}${v===null?'<span class="tag">证据不足（不计入分母）</span>':''}<small>${esc(r.reasons[i])}</small></div>`).join('')}<h4>匹配馆藏 / 活动</h4>${r.matches.map(m=>`<div class="match"><b>${esc(m.name)}</b><p>${esc(m.conditions)}</p><small>限制：${esc(m.limits)}</small></div>`).join('')||'<p>暂无匹配资源，不能据此推荐活动。</p>'}<h4>缺失信息与不确定性</h4><ul>${r.uncertainties.map(u=>`<li>${esc(u)}</li>`).join('')}</ul></section>`;}
function insights(){const gs=groups();return `${filters()}<div class="toolbar"><label>机会排序 <select id="sort">${[['index','机会指数'],['n','讨论规模'],['strength','信号强度'],['coverage','证据覆盖率']].map(([v,l])=>`<option value="${v}" ${sort===v?'selected':''}>${l}</option>`).join('')}</select></label>${button('导出主题结果','export-insights')}</div><div class="resource-grid">${gs.map(g=>`<article class="panel"><div class="panel-title">${tag('规则主题分群','teal')}<strong>${g.index} <small>/ 100</small></strong></div><h3>${g.theme}</h3><div class="mini-stats"><span><b>${g.n}</b>讨论量 / 条</span><span><b>${Math.round(g.n/(analyzed().length||1)*100)}%</b>样本占比</span><span><b>${g.strength}</b>平均信号</span></div><p>明确计划占比 ${g.explicit}% · 证据覆盖率 ${g.coverage}% · 历史评论 ${g.history} 条</p><blockquote>${esc(g.rows[0].post.text)}</blockquote><h4>需求 → 资源 → 宣传方向</h4><p>${g.theme}需求 → ${esc(g.rows.find(r=>r.matches.length)?.matches[0].name||'资源待补充')} → ${g.theme==='亲子教育与互动'?'基于原文复核亲子讲解与互动信息':'围绕具体体验制作资源介绍'}</p>${tag('现有宣传覆盖：待核实')}<details><summary>查看指数依据与原文（${g.n}）</summary><p>规模 ${Math.round(Math.min(g.n/30,1)*100)}×20% + 强度 ${g.strength}×25% + 契合 ${g.fit}×25% + 覆盖 ${g.coverage}×20% + 执行便利 ${g.difficulty}×10%。执行便利是演示预设，需运营审核。历史到访评论只启发体验改进，不证明新的获客机会。</p>${g.rows.map(r=>`<button class="evidence-link" data-select="${esc(r.post.id)}">${esc(r.post.id)} · ${esc(r.post.text)}</button>`).join('')}</details><div class="card-bottom"><button data-topic="${g.theme}">查看原始内容</button><button class="primary" data-strategy="${g.theme}">生成营销策略 ↗</button></div></article>`).join('')||empty}</div>`;}
function makePlan(t){const g=aggregate(analyzed().filter(r=>r.post.review!=='rejected')).find(g=>g.theme===t),matches=[...new Map((g?.rows||[]).flatMap(r=>r.matches).map(r=>[r.id,r])).values()];return `营销主题：${t}\n\n1. 机会与核心证据\n${g?.n||0} 条实际来源样本，平均信号 ${g?.strength||0}。代表原文：“${g?.rows[0]?.post.text||'暂无'}”。宣传覆盖待核实。\n历史到访评论不等于新的潜在观众需求；本方案采用当前筛选、排除人工拒绝项后的数据。\n证据出处：${(g?.rows||[]).slice(0,5).map(r=>r.post.id+' · '+(r.post.evidenceUrl||r.post.sourceUrl||'来源未核实')).join('\n')}\n示例馆资源为虚构，评论来自其他馆，资源迁移与活动条件须重新核实。\n\n2. 目标需求群体\n表达${t}需求的内容群体；不推断个人身份，不生成个人定向名单。\n\n3. 推荐资源\n${matches.map(r=>`${r.name}：${r.conditions}；限制：${r.limits}`).join('\n')||'无匹配资源，暂不建议执行推广。'}\n\n4. 内容切入点\n${t==='亲子教育与互动'?'围绕原文已出现的亲子、学习、互动线索制作资源说明；一般亲子表达不等于手作需求。':'用资源实景、流程说明和限制信息回应具体需求。'}\n\n5. A/B 宣传文案（模板生成，发布前人工核实）\nA：${t==='亲子教育与互动'?'周末亲子文化探索：先了解展览内容与参与条件。':'从'+t+'出发，发现馆藏背后的故事。'}\nB：${t==='亲子教育与互动'?'和孩子一起读懂展品背后的故事。':'给好奇心一个去处：一起探索'+t+'。'}\n请查阅开放时间与预约条件；活动余位、年龄要求及拍摄规则以馆方确认信息为准。\n\n6. 平台关键词\n${t}、古代科技、文化体验、云川历史工艺博物馆（虚构）。建议以授权运营账号测试内容。\n\n7. 内容与线下建议\n制作 30 秒体验流程短片；展示参与条件；小规模开展预约活动；拍照需求须先核查商业摄影限制。\n馆方规则：${state.museum.restrictions}；${state.museum.hours}；${state.museum.booking}。\n\n8. 效果验证\n对照相同周期、平台和预算，分别测试 A/B；记录内容点击率（点击/曝光）、活动页访问率（访问/点击）、报名转化率（报名/活动页访问）、实际到场率（到场/报名）。真实投放数据尚未接入。`;}
function studio(){const plan=state.plans[theme]||makePlan(theme);return `<div class="studio-layout"><section class="panel"><div class="panel-title"><h3>策略编辑器</h3>${tag('模板生成 · 可编辑','teal')}</div><label>需求主题 <select id="studio-theme">${themes.map(t=>`<option ${theme===t?'selected':''}>${t}</option>`).join('')}</select></label><div class="toolbar">${button('重新生成','generate',true)}${button('保存方案','save-plan')}${button('复制','copy-plan')}${button('导出 Markdown','export-plan')}</div><textarea id="plan" class="plan">${esc(plan)}</textarea><small>方案保存在当前浏览器；修改资源后点击重新生成以采用最新规则。</small></section><div><section class="panel"><h3>发布前核实</h3><p>☐ 活动资源与开放时间</p><p>☐ 预约、年龄及拍摄限制</p><p>☐ 宣传覆盖与执行能力</p><p>☐ 对照周期与指标口径</p></section><section class="panel"><div class="panel-title"><h3>A/B 效果沙盘</h3>${tag('演示输入')}</div><p class="muted">手动调整假设数值，理解指标计算；并非真实投放结果。</p>${['A','B'].map((x,i)=>`<fieldset><legend>文案 ${x}</legend><label>曝光数<input type="number" min="0" value="${i?1200:1000}" id="exp${x}"></label><label>点击数<input type="number" min="0" value="${i?72:50}" id="clk${x}"></label><p id="rate${x}">演示点击率 ${i?'6.0':'5.0'}%</p></fieldset>`).join('')}</section></div></div>`;}
function download(name,text,type='application/json'){const u=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function modal(content){const d=document.createElement('dialog');d.innerHTML=`<div class="modal-head"><h3>数据与资源编辑</h3><button id="close-modal">关闭 ×</button></div>${content}`;document.body.append(d);d.showModal();$('#close-modal').onclick=()=>d.remove();return d;}
function editResource(id){const existing=state.resources.find(r=>r.id===id),r=existing||{id:'R'+Date.now(),name:'',intro:'',type:'活动',keywords:'',scenes:'',audience:'',conditions:'',limits:''},labels={name:'名称',intro:'简介',type:'类型',keywords:'关键词（空格分隔，参与匹配）',scenes:'适合场景',audience:'对应客群',conditions:'参与条件',limits:'实际限制'};const d=modal(`<form id="resource-form">${Object.entries(labels).map(([k,l])=>`<label>${l}<input name="${k}" value="${esc(r[k])}" required></label>`).join('')}<button class="primary">保存并重新匹配</button></form>`);$('#resource-form').onsubmit=e=>{e.preventDefault();const value={...r,...Object.fromEntries(new FormData(e.target))};if(existing)state.resources=state.resources.map(x=>x.id===id?value:x);else state.resources.push(value);persist();d.remove();render();toast('资源已保存，匹配结果已更新');};}
function parseCSV(text){const rows=[];let row=[],field='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){field+='"';i++;}else quoted=!quoted;}else if(c===','&&!quoted){row.push(field);field='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(field);if(row.some(x=>x))rows.push(row);row=[];field='';}else field+=c;}if(quoted)throw Error('CSV 引号未闭合');row.push(field);if(row.some(x=>x))rows.push(row);const head=rows.shift()?.map(x=>x.trim().replace(/^\uFEFF/,''));if(!head?.includes('text'))throw Error('CSV 必须包含 text 列');return rows.map(r=>Object.fromEntries(head.map((h,i)=>[h,r[i]||''])));}
async function importFile(file){try{const txt=await file.text(),raw=file.name.endsWith('.json')?JSON.parse(txt):parseCSV(txt);if(!Array.isArray(raw))throw Error('JSON 须为对象数组');pending=[];importErrors=[];const ids=new Set(state.posts.map(p=>p.id));raw.forEach((p,i)=>{const id=String(p.id||'I'+Date.now()+'-'+i);if(!p.text||typeof p.text!=='string'||!p.text.trim()){importErrors.push(`第 ${i+1} 行：text 必须是非空字符串`);return;}if(ids.has(id)){importErrors.push(`第 ${i+1} 行：ID 重复 ${id}`);return;}if(p.date&&(!/^\d{4}-\d{2}-\d{2}$/.test(p.date)||!Number.isFinite(Date.parse(p.date))||new Date(p.date).toISOString().slice(0,10)!==p.date)){importErrors.push(`第 ${i+1} 行：date 必须为有效 YYYY-MM-DD`);return;}ids.add(id);pending.push({id,platform:String(p.platform||'导入文本'),date:p.date||'',text:p.text.trim(),source:'用户导入（真实性未核实）',declaredSource:String(p.source||''),sourceUrl:safeUrl(p.sourceUrl),evidenceUrl:safeUrl(p.evidenceUrl||p.sourceUrl),kind:'imported',collectedAt:new Date().toISOString(),provenance:'用户提供的文本与链接，系统未独立验证来源',analyzed:false});});const d=modal(`<h3>导入预览</h3><p>有效 ${pending.length} 条，错误 ${importErrors.length} 条。保留正文、日期、平台及安全来源链接；来源声明待核实；身份字段丢弃。</p><p class="danger">${importErrors.map(esc).join('<br>')}</p>${pending.slice(0,5).map(p=>`<blockquote>${esc(p.text)}</blockquote>`).join('')}<button id="confirm-import" class="primary" ${pending.length?'':'disabled'}>确认导入有效行</button>`);$('#confirm-import').onclick=()=>{state.posts.push(...pending);persist();d.remove();render();toast('导入完成，请点击开始分析');};}catch(e){toast('导入失败：'+e.message);}}
function bind(){document.querySelectorAll('a[href^="#"]').forEach(a=>a.onclick=e=>{e.preventDefault();go(a.hash.slice(1));});['search','theme-filter','intent-filter','source-filter','from','to'].forEach(id=>{const el=$('#'+id);if(el)el.onchange=()=>{({search:v=>search=v,'theme-filter':v=>filterTheme=v,'intent-filter':v=>filterIntent=v,'source-filter':v=>filterSource=v,from:v=>from=v,to:v=>to=v}[id])(el.value);render();};});document.querySelectorAll('[data-select],[data-signal]').forEach(el=>el.onclick=()=>{selected=el.dataset.select||el.dataset.signal;testResult=null;go('analysis');});document.querySelectorAll('[data-topic]').forEach(el=>el.onclick=()=>{filterTheme=el.dataset.topic;go('social');});document.querySelectorAll('[data-strategy]').forEach(el=>el.onclick=()=>{theme=el.dataset.strategy;go('studio');});document.querySelectorAll('[data-edit-resource]').forEach(el=>el.onclick=()=>editResource(el.dataset.editResource));document.querySelectorAll('[data-delete-resource]').forEach(el=>el.onclick=()=>{const d=modal(`<p>删除此资源将立即影响匹配结果。</p><button class="primary" id="confirm-delete">确认删除</button>`);$('#confirm-delete').onclick=()=>{state.resources=state.resources.filter(r=>r.id!==el.dataset.deleteResource);persist();d.remove();render();};});document.querySelectorAll('[data-weight]').forEach(el=>el.oninput=()=>{state.weights[+el.dataset.weight]=+el.value;persist();if(testResult)testResult=analyze(testResult.post,state.resources,state.weights);render();});if($('#museum-form'))$('#museum-form').onsubmit=e=>{e.preventDefault();state.museum=Object.fromEntries(new FormData(e.target));persist();render();toast('资料已更新');};bindSources();if($('#file'))$('#file').onchange=e=>e.target.files[0]&&importFile(e.target.files[0]);if($('#sort'))$('#sort').onchange=e=>{sort=e.target.value;render();};if($('#studio-theme'))$('#studio-theme').onchange=e=>{theme=e.target.value;render();};if($('#test-text'))$('#test-text').oninput=e=>draft=e.target.value;['A','B'].forEach(x=>['exp','clk'].forEach(k=>{if($('#'+k+x))$('#'+k+x).oninput=()=>{const exp=+$('#exp'+x).value,clk=+$('#clk'+x).value;$('#rate'+x).textContent=exp<=0||clk<0||clk>exp?'请填写有效数值（点击数≤曝光数）':'演示点击率 '+(clk/exp*100).toFixed(1)+'%';};}));document.querySelectorAll('[data-action]').forEach(el=>el.onclick=async()=>{switch(el.dataset.action){case 'start':go('social');break;case 'clear':search=filterTheme=filterIntent=filterSource=filterKind=filterReview=from=to='';render();break;case 'import':$('#file').click();break;case 'samples':{const d=dedupe(posts,state.posts);state.posts.push(...d.items);persist();render();toast('载入 '+d.items.length+' 条真实研究评论，跳过 '+d.duplicates+' 条重复');break;}case 'fetch-live':await loadLive(false);break;case 'next-live':await loadLive(true);break;case 'export-runs':download('museradar-runs.json',JSON.stringify(state.runs,null,2));break;case 'analyze':{const ids=new Set(filtered().map(r=>r.post.id));state.posts.forEach(p=>{if(ids.has(p.id))p.analyzed=true;});persist();selected=filtered()[0]?.post.id;testResult=null;go('analysis');toast('规则分析完成');break;}case 'export-posts':download('museradar-posts.json',JSON.stringify(filtered().map(r=>r.post),null,2));break;case 'export-insights':download('museradar-insights.json',JSON.stringify(groups(),null,2));break;case 'reset-weights':state.weights=[...defaults];persist();if(testResult)testResult=analyze(testResult.post,state.resources,state.weights);render();break;case 'test':if(!draft.trim()){toast('请先输入文本');break;}testResult=analyze({id:'TEST',text:draft,source:'手动测试（来源未核实）',kind:'manual',analyzed:true},state.resources,state.weights);render();break;case 'add-test':if(!draft.trim()){toast('请先输入文本');break;}selected='T'+Date.now();state.posts.push({id:selected,text:draft,source:'手动输入（来源未核实）',kind:'manual',platform:'本地文本',date:'',analyzed:true});testResult=null;persist();render();toast('已加入数据集，统计已同步');break;case 'add-resource':editResource();break;case 'generate':{const d=modal('<p>重新生成将覆盖当前主题的已保存方案。</p><button id="regen" class="primary">确认重新生成</button>');$('#regen').onclick=()=>{state.plans[theme]=makePlan(theme);persist();d.remove();render();};break;}case 'save-plan':state.plans[theme]=$('#plan').value;persist();toast('方案已保存至浏览器');break;case 'copy-plan':try{await navigator.clipboard.writeText($('#plan').value);toast('已复制方案');}catch{$('#plan').select();document.execCommand('copy');toast('已选择并复制方案');}break;case 'export-plan':download('MuseRadar-'+theme+'.md',$('#plan').value,'text/markdown;charset=utf-8');break;default:if(el.dataset.action.startsWith('kpi'))go(el.dataset.action==='kpi0'?'social':'insights');}});}
function sourcePanel(){const terms=[...new Set(dictionaries.flat())].map(term=>({term,n:state.posts.filter(p=>p.analyzed&&p.text.toLowerCase().includes(term.toLowerCase())).length})).filter(t=>t.n>1).sort((a,b)=>b.n-a.n).slice(0,16);return `<section class="panel"><div class="panel-title"><div><div class="eyebrow">REAL SOURCES / 从真实讨论开始</div><h3>读取公开评论，保留原始证据</h3></div>${tag('无虚构评论','teal')}</div><div class="source-grid"><div class="source-tile"><h4>01 · 已载入的中文历史评论</h4><strong>${posts.length} 条 / 4 家博物馆</strong><p>研究作者公开的马蜂窝中文评论转录。保留原文、日期、博物馆、PDF 页码与数据集 DOI；不包含昵称。</p><small>${esc(researchSource.author)} · ${researchSource.published} · CC BY 4.0</small><p>${sourceLink(researchSource.url,'查看研究数据集')} · <a href="./real-reviews.json" download>下载当前研究快照</a> · <a href="./provenance.json" target="_blank">处理清单 ↗</a></p><p class="muted">这批历史反馈不是实时趋势，不用于计算新观众高潜力信号。虚构馆资源仅作跨馆启发匹配。</p></div><div class="source-tile"><h4>02 · 按需检索真实公开讨论</h4><p>直接调用 HN Search 公开评论接口，不读取参考网站的私有后端。以英文讨论为主，可能包含无关内容，需人工复核。</p><label>检索关键词<input id="live-query" value="${esc(liveState.query)}" placeholder="museum / science museum / children museum" ${liveState.busy?'disabled':''}></label><label>原始发布时间<select id="live-days" ${liveState.busy?'disabled':''}>${[[0,'不限时间'],[30,'最近 30 天'],[90,'最近 90 天'],[365,'最近一年']].map(([v,l])=>`<option value="${v}" ${+liveState.days===v?'selected':''}>${l}</option>`).join('')}</select></label><div class="toolbar"><button class="primary" data-action="fetch-live" ${liveState.busy?'disabled':''}>${liveState.busy?'正在获取真实评论…':'获取真实评论并分析'}</button><button data-action="next-live" ${liveState.busy||!liveState.last||liveState.last.page+1>=liveState.last.pages?'disabled':''}>下一页</button></div><small>每页最多 50 条；按 ID 与正文去重。失败显示错误，保留现有数据，不注入模拟内容。</small></div></div>${liveState.error?`<div class="notice error" role="alert">读取失败：${esc(liveState.error)} 当前数据未被替换。</div>`:''}${liveState.last?`<p class="notice">上次真实请求：${esc(liveState.last.query)} · 原始响应 ${liveState.last.received} 条 · 排除空文/招聘 ${liveState.last.excluded} 条 · 新增 ${liveState.last.added} 条 · 重复 ${liveState.last.duplicates} 条 · 第 ${liveState.last.page+1} 页 · ${esc(liveState.last.fetchedAt)}<br>${sourceLink(liveState.last.requestUrl,'查看原始 API 响应')}</p>`:''}<details><summary>运行记录（${state.runs.length}）与数据边界</summary>${state.runs.slice(0,8).map(r=>`<p>${esc(r.fetchedAt)} · ${esc(r.query)} · 新增 ${r.added} · 重复 ${r.duplicates} · 第 ${r.page+1} 页</p>`).join('')||'<p>尚无在线读取记录；内置研究快照不冒充在线请求。</p>'}${button('导出读取记录','export-runs')}<p>平台索引存在延迟与覆盖偏差。历史原文中的门票、开放时间和活动规则不是当前事实；真实运营请另行核实。原文链接可能失效，研究快照可用 PDF 页码复核。</p></details></section><section class="panel"><div class="panel-title"><h3>从当前样本发现话题</h3>${tag('词典命中条数 · 非平台热度')}</div><div class="word-cloud">${terms.map(t=>`<button data-word="${esc(t.term)}" style="font-size:${12+Math.min(10,t.n/8)}px">${esc(t.term)} <small>${t.n}</small></button>`).join('')||empty}</div></section>`;}
async function loadLive(next){if(liveState.busy)return;const query=$('#live-query')?.value.trim()||liveState.query,days=+($('#live-days')?.value??liveState.days);const page=next&&query===liveState.query&&days===liveState.days?liveState.page+1:0;liveState={...liveState,query,days,page,busy:true,error:''};render();try{const result=await fetchPublicComments({query,days,page}),clean=dedupe(result.items,state.posts),run={query,days,page,received:result.received,excluded:result.excluded,added:clean.items.length,duplicates:clean.duplicates+result.duplicates,fetchedAt:result.fetchedAt,requestUrl:result.requestUrl,pages:result.pages};state.posts.push(...clean.items);state.runs.unshift(run);state.runs=state.runs.slice(0,30);liveState.last=run;search=filterTheme=filterIntent=filterKind=filterReview=from=to='';filterSource='HN Search · 公开讨论';persist();toast('真实读取完成：新增 '+clean.items.length+' 条；不会补造结果');}catch(e){liveState.error=e.message||'无法连接公开评论接口';}finally{liveState.busy=false;render();}}
function bindSources(){document.querySelectorAll('[data-source-link]').forEach(a=>a.onclick=e=>e.stopPropagation());document.querySelectorAll('[data-word]').forEach(b=>b.onclick=()=>{search=b.dataset.word;filterTheme=filterIntent=filterSource=filterKind=filterReview=from=to='';render();});document.querySelectorAll('[data-review-id]').forEach(b=>b.onclick=()=>{state.reviews[b.dataset.reviewId]=b.dataset.reviewValue;persist();render();toast('人工复核已保存，机会统计已同步');});for(const id of ['kind-filter','review-filter']){const el=$('#'+id);if(el)el.onchange=()=>{if(id==='kind-filter')filterKind=el.value;else filterReview=el.value;render();};}}
window.addEventListener('hashchange',()=>{page=location.hash.slice(1)||'overview';render();});render();
